export const SCREEN_BALANCE_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu waktu layar",q:"'Waktu layar' (screen time) adalah...",options:["Jumlah waktu yang dihabiskan memakai perangkat dengan layar (HP, tablet, komputer, TV)","Jumlah waktu yang dihabiskan di luar rumah tanpa memakai perangkat, seperti bermain dan berolahraga","Tingkat kecerahan layar HP saat membuka aplikasi sepanjang hari"],answer:0,explain:"Waktu layar mencakup semua perangkat berlayar: bermain game, menonton video, media sosial, & lainnya.",hint:"Total waktu di semua perangkat berlayar, atau hanya TV?"},
{n:2,type:"mcq",micro:"Kenapa keseimbangan penting",q:"Kenapa penting menyeimbangkan waktu layar dengan aktivitas lain?",options:["Supaya semua waktu bisa dihabiskan di layar, karena aktivitas lain tidak memberi manfaat bagi kesehatan","Supaya tetap ada waktu untuk tidur, bergerak, bertemu orang langsung, & kegiatan lain yang juga penting bagi kesehatan","Supaya layar tidak dipakai lagi, sebab menurut aturan kesehatan penggunaan layar berbahaya bagi anak"],answer:1,explain:"Keseimbangan bukan berarti anti-layar, tapi memastikan hal-hal penting lain (tidur, gerak, hubungan) tidak terabaikan.",hint:"Menjaga waktu untuk hal penting lain, atau harus dihindari total / tak berpengaruh?"},
{n:3,type:"mcq",micro:"Dampak pada tidur",q:"Memakai layar (terutama HP) sesaat sebelum tidur bisa mengganggu tidur karena...",options:["Karena layar HP membuat tubuh langsung tertidur nyenyak, sehingga kualitas tidur meningkat setelah memakainya","Karena cahaya layar tidak memengaruhi tubuh dan otak, jadi tak berhubungan dengan tidur","Cahaya layar & konten yang merangsang otak bisa membuat lebih sulit mengantuk & menurunkan kualitas tidur"],answer:2,explain:"Cahaya biru & rangsangan konten (video seru, notifikasi) membuat otak tetap 'terjaga' saat seharusnya bersiap tidur.",hint:"Mengganggu & menurunkan kualitas tidur, atau justru bikin cepat ngantuk?"},
{n:4,type:"mcq",micro:"Dampak pada mata & tubuh",q:"Menatap layar terlalu lama tanpa jeda bisa menyebabkan...",options:["Mata lelah/kering, sakit kepala, & postur tubuh yang buruk (leher/punggung pegal)","Mata menjadi lebih tajam, tubuh lebih bugar, dan postur makin tegak karena layar melatih otot","Tidak ada pengaruh pada tubuh, sebab tubuh manusia tidak lelah hanya karena menatap layar"],answer:0,explain:"Tubuh butuh jeda dari posisi & fokus mata yang sama terus-menerus. Aturan '20-20-20' (tiap 20 menit, lihat jarak 20 kaki selama 20 detik) membantu.",hint:"Mata lelah & postur buruk, atau tak ada efek?"},
{n:5,type:"mcq",micro:"Dampak pada aktivitas fisik",q:"Waktu layar yang berlebihan bisa mengurangi waktu untuk...",options:["Hanya memengaruhi orang dewasa, bukan anak-anak","Bergerak/berolahraga, yang penting bagi kesehatan tubuh & suasana hati","Tidak mengurangi aktivitas lain karena bisa dilakukan sambil bergerak"],answer:1,explain:"Waktu yang dihabiskan duduk menatap layar adalah waktu yang tidak dipakai bergerak aktif, keduanya bersaing.",hint:"Mengurangi waktu bergerak, atau tak berpengaruh?"},
{n:6,type:"mcq",micro:"Dampak pada hubungan tatap muka",q:"Terlalu sering fokus pada layar saat bersama orang lain (mis. saat makan bersama keluarga) bisa...",options:["Meningkatkan kualitas kebersamaan dan membuat orang sekitar merasa dihargai oleh yang memegang HP","Tidak memengaruhi hubungan antar orang, karena perhatian ke layar dan orang lain bisa dibagi sempurna","Mengurangi kualitas kebersamaan & membuat orang di sekitar merasa kurang diperhatikan"],answer:2,explain:"Perhatian yang terbagi ke layar mengurangi momen nyata bersama orang yang ada di depan kita.",hint:"Mengurangi kualitas kebersamaan, atau selalu lebih baik?"},
{n:7,type:"mcq",micro:"Aktif vs pasif memakai layar",q:"Beda pemakaian layar yang 'aktif' (membuat/belajar/berkarya) dengan yang 'pasif' (scroll tanpa tujuan):",options:["Aktif melibatkan pikiran & menghasilkan sesuatu; pasif cenderung hanya menyerap tanpa banyak keterlibatan","Aktif berarti hanya menonton tanpa berpikir, sedangkan pasif berarti membuat sesuatu yang baru, jadi keduanya soal istilah","Tidak ada bedanya, sebab setiap pemakaian layar berdampak sama"],answer:0,explain:"Tidak semua waktu layar sama. Membuat video, belajar coding, atau menggambar digital berbeda dari scroll tanpa henti.",hint:"Aktif melibatkan pikiran, pasif hanya menyerap, atau sama saja?"},
{n:8,type:"mcq",micro:"Jeda kecil membantu",q:"Mengambil jeda singkat (berdiri, meregangkan badan, melihat jauh) setiap beberapa puluh menit saat memakai layar berguna untuk...",options:["Membuat layar lebih terang dan baterai lebih awet, karena tubuh yang bergerak membantu perangkat","Mengurangi kelelahan mata & tubuh dari posisi diam yang lama","Mengurangi tugas yang selesai, sehingga jeda sebaiknya dihindari"],answer:1,explain:"Jeda kecil yang rutin membantu tubuh & mata pulih sebelum kelelahan menumpuk.",hint:"Mengurangi kelelahan, atau membuang waktu?"},
{n:9,type:"order",micro:"Menyeimbangkan hari dengan layar",q:"Urutkan contoh cara menjaga hari tetap seimbang antara layar & aktivitas lain.",items:["Selesaikan tugas penting/belajar dulu sebelum bersantai dengan layar","Sisihkan waktu layar untuk hiburan dengan batas yang disepakati","Luangkan waktu untuk bergerak/aktivitas fisik & bertemu orang langsung","Berhenti memakai layar cukup lama sebelum tidur untuk istirahat yang baik"],answer:[0,1,2,3],explain:"Prioritas dulu → hiburan dengan batas → gerak & sosial → berhenti sebelum tidur. Urutan ini menjaga hal penting tidak terlewat karena kelamaan di layar.",hint:"Menyelesaikan tugas penting dilakukan sebelum atau sesudah waktu layar untuk hiburan?"},
{n:10,type:"mcq",micro:"Waktu layar bukan musuh",q:"Cara pandang yang sehat tentang waktu layar:",options:["Layar adalah sesuatu yang harus dipakai sebanyak mungkin sepanjang hari tanpa batas, karena semakin lama dipakai semakin banyak manfaatnya","Layar adalah musuh yang harus dihindari oleh banyak orang, termasuk untuk belajar, berkomunikasi, dan berkarya","Layar adalah alat yang bermanfaat bila dipakai dengan seimbang & sadar, bukan sesuatu yang harus dihindari sepenuhnya"],answer:2,explain:"Layar membuka banyak manfaat (belajar, kreativitas, koneksi). Yang penting keseimbangan & kesadaran, bukan menghindarinya sama sekali.",hint:"Alat bermanfaat bila seimbang, atau harus dihindari total / makin banyak makin baik?"},
{n:11,type:"tf",micro:"Semua waktu layar sama",q:"Benar atau Salah: Semua jenis waktu layar (belajar coding, menonton video edukasi, scroll media sosial tanpa tujuan) memberi dampak yang sama pada diri kita.",answer:false,explain:"Sebaliknya, jenis aktivitasnya berpengaruh, belajar aktif berbeda dampaknya dari scroll pasif tanpa tujuan, meski keduanya 'waktu layar'.",hint:"Semua sama, atau jenis aktivitasnya berpengaruh?"},
{n:12,type:"tf",micro:"Tidur & layar berhubungan",q:"Benar atau Salah: Ada hubungan nyata antara pemakaian layar sebelum tidur dengan kualitas & durasi tidur seseorang.",answer:true,explain:"Cahaya & rangsangan konten memengaruhi jam biologis tubuh & kesiapan otak untuk beristirahat.",hint:"Ada hubungan nyata, atau tidak berhubungan sama sekali?"},
{n:13,type:"mcq",micro:"Kesadaran adalah langkah pertama",q:"Langkah pertama menuju keseimbangan layar yang lebih baik:",options:["Menyadari & memeriksa pola pemakaian layarmu sendiri (berapa lama, untuk apa) sebelum membuat perubahan","Langsung membuang perangkat tanpa memeriksa kebiasaanmu, agar tak ada godaan untuk memakainya","Menebak-nebak saja pemakaianmu tanpa mencatat atau memeriksa, lalu mengikuti kebiasaan teman-temanmu"],answer:0,explain:"Kesadaran akan pola yang ada memberi dasar untuk membuat perubahan yang realistis, bukan aturan sembarangan.",hint:"Sadari pola dulu, atau langsung larang total / abaikan?"},
{n:14,type:"mcq",micro:"Fitur 'waktu layar' di perangkat",q:"Banyak perangkat punya fitur yang menunjukkan berapa lama & untuk apa layar dipakai. Fitur ini berguna untuk...",options:["Membuat perangkat lebih cepat dan hemat baterai, tanpa memberi tahu pola pemakaian kita sendiri","Memberi gambaran nyata (bukan tebakan) tentang kebiasaan pemakaian, sebagai dasar membuat perubahan","Menjadi bahan perbandingan untuk menyombongkan diri di depan teman yang pemakaian layarnya lebih banyak"],answer:1,explain:"Melihat data nyata sering mengejutkan & membantu kita membuat keputusan berdasarkan fakta, bukan perasaan.",hint:"Memberi gambaran nyata untuk berubah, atau tak berguna / hanya untuk memata-matai?"},
{n:15,type:"mcq",micro:"Zona/waktu bebas layar",q:"Menetapkan 'zona bebas layar' (mis. meja makan) atau 'waktu bebas layar' (mis. 1 jam sebelum tidur) membantu karena...",options:["Membuat kebiasaan baik terasa lebih sulit dan melelahkan, karena kita harus terus mengatur ulang batas yang berbeda-beda setiap harinya","Membuat orang tak bisa memakai layar sepanjang hari, termasuk di tempat lain","Menciptakan batas yang jelas & konsisten, memudahkan kebiasaan baik terbentuk tanpa harus memutuskan setiap saat"],answer:2,explain:"Batas yang jelas ('di sini tidak ada layar') lebih mudah dipatuhi daripada memutuskan 'boleh atau tidak' setiap saat.",hint:"Batas jelas memudahkan kebiasaan baik, atau merumitkan / tak ada beda?"},
{n:16,type:"tf",micro:"Keseimbangan berbeda tiap orang",q:"Benar atau Salah: Ada satu angka pasti waktu layar 'seimbang' yang berlaku sama persis untuk semua orang di semua situasi.",answer:false,explain:"Sebaliknya, jumlah waktu layar yang seimbang bisa berbeda tergantung usia, kebutuhan, & jenis aktivitas. Yang penting prinsipnya (tidak mengorbankan tidur, gerak, hubungan, tugas penting), bukan angka kaku untuk semua.",hint:"Berbeda tergantung konteks, atau ada satu angka pasti untuk semua?"},
{n:17,type:"mcq",micro:"Layar untuk belajar tetap perlu jeda",q:"Meski memakai layar untuk belajar (tugas sekolah, riset), tetap penting untuk...",options:["Mengambil jeda berkala & tidak lupa aktivitas lain, karena tubuh & mata tetap butuh istirahat meski tujuannya produktif","Terus memakai layar tanpa jeda sampai tugas selesai, sebab layar untuk belajar membuat mata dan tubuh tak lelah","Menghabiskan seluruh waktu luang di layar juga, karena kegiatan produktif membuat tubuh tidak lagi membutuhkan istirahat atau kegiatan lain"],answer:0,explain:"Tujuan produktif tidak menghapus kebutuhan tubuh akan jeda. Kelelahan tetap menumpuk meski aktivitasnya bermanfaat.",hint:"Tetap perlu jeda, atau tidak perlu karena untuk belajar?"},
{n:18,type:"mcq",micro:"Menikmati tanpa rasa bersalah",q:"Menikmati waktu layar untuk hiburan (game, video, media sosial) dalam jumlah yang wajar & disengaja adalah...",options:["Kebiasaan buruk yang harus dihindari sepenuhnya, sehingga setiap kali bermain atau menonton kita wajib merasa bersalah","Bagian normal dari hidup seimbang, tidak perlu selalu dirasa bersalah selama proporsinya wajar","Tanda bahwa seseorang kecanduan dan bermasalah, berapa lama pun ia memakainya"],answer:1,explain:"Keseimbangan bukan berarti nol hiburan digital, melainkan proporsi yang wajar bersama aktivitas penting lainnya.",hint:"Bagian normal yang wajar, atau selalu buruk / sebanyak mungkin?"},
{n:19,type:"mcq",micro:"Menentukan prioritas harian",q:"Cara sederhana menjaga keseimbangan setiap hari:",options:["Nikmati dulu waktu layar sepuasnya, baru kerjakan tugas, tidur, dan bergerak dengan sisa tenaga","Hindari layar sepanjang hari, bahkan untuk tugas dan hiburan, agar tak ada risiko bagi kesehatan","Selesaikan hal-hal penting (tugas, tidur cukup, gerak) dulu, baru nikmati waktu layar untuk hiburan dengan tenang"],answer:2,explain:"Menempatkan hal penting lebih dulu membuat waktu layar untuk hiburan terasa sebagai hadiah, bukan pengganti kewajiban.",hint:"Hal penting dulu baru layar untuk hiburan, atau layar dulu sebanyak mungkin?"},
{n:20,type:"open",micro:"Petakan pola waktu layarmu",q:"Selama satu hari (kemarin atau hari biasa), perkirakan & catat: (a) berapa lama & untuk apa saja kamu memakai layar (buat daftar per aktivitas), (b) mana yang termasuk pemakaian 'aktif' & mana 'pasif', (c) satu hal penting (tidur/gerak/waktu bersama orang) yang menurutmu jadi terkurangi karena waktu layar, (d) satu perubahan kecil yang akan kamu coba minggu ini.",explain:"Jawaban baik: catatan yang jujur & spesifik (bukan perkiraan sangat kasar), klasifikasi aktif/pasif yang masuk akal, identifikasi hal penting yang benar-benar terkurangi (spesifik, bukan generik), & perubahan kecil yang realistis & bisa benar-benar dicoba minggu ini.",hint:"Untuk (b), pikirkan apakah aktivitas itu melibatkan pikiran & menghasilkan sesuatu, atau hanya menyerap konten tanpa tujuan tertentu.",sample:"(a) Perkiraan kemarin: belajar/tugas sekolah di laptop 1,5 jam; menonton video hiburan 1 jam; media sosial (scroll) sekitar 45 menit tersebar sepanjang hari; bermain game 1 jam; nonton film bersama keluarga 1,5 jam. Total sekitar 5,5-6 jam. (b) Aktif: belajar/tugas (melibatkan pikiran & menghasilkan sesuatu), bermain game (kadang melibatkan strategi/kreativitas). Pasif: scroll media sosial tanpa tujuan jelas, menonton video hanya untuk mengisi waktu. (c) Hal yang terkurangi: aku sadar waktu tidurku jadi lebih pendek dari biasanya karena aku scroll HP sekitar 30 menit sebelum tidur, & aku juga jadi jarang jalan kaki sore karena keasyikan main game setelah pulang sekolah. (d) Perubahan kecil: minggu ini aku akan meletakkan HP di ruang lain 30 menit sebelum jam tidur biasa, & menggantinya dengan membaca buku atau mengobrol sebentar dengan keluarga, supaya tidurku lebih baik."},
{n:21,type:"classify",micro:"Pemakaian aktif vs pasif",q:"Kelompokkan tiap aktivitas layar ke 'Aktif (melibatkan pikiran/berkarya)' atau 'Pasif (menyerap tanpa banyak keterlibatan)'.",items:["Membuat video pendek & mengeditnya","Scroll tanpa henti tanpa tujuan tertentu","Belajar bahasa baru lewat aplikasi interaktif","Menonton video secara acak berjam-jam tanpa memilih dengan sengaja"],groups:["Aktif (melibatkan pikiran/berkarya)","Pasif (menyerap tanpa banyak keterlibatan)"],answer:{"Aktif (melibatkan pikiran/berkarya)":["Membuat video pendek & mengeditnya","Belajar bahasa baru lewat aplikasi interaktif"],"Pasif (menyerap tanpa banyak keterlibatan)":["Scroll tanpa henti tanpa tujuan tertentu","Menonton video secara acak berjam-jam tanpa memilih dengan sengaja"]},explain:"Aktif: berkarya & melibatkan pikiran secara sengaja. Pasif: menyerap konten tanpa tujuan atau pilihan yang disengaja.",hint:"Melibatkan pikiran & berkarya, atau menyerap tanpa tujuan?"},
{n:22,type:"mcq",micro:"Desain yang dirancang menarik perhatian",q:"Banyak aplikasi dirancang dengan fitur (scroll tanpa akhir, notifikasi, warna mencolok) yang bertujuan untuk...",options:["Membuat kita terus memakai aplikasi itu selama mungkin, karena itu menguntungkan pembuatnya","Membantu kita menyelesaikan pekerjaan lebih cepat dan segera berhenti, karena itulah tujuan para pembuat aplikasi","Menjaga kesehatan mata dan tidur pengguna, karena pembuat aplikasi mengutamakan kesehatan"],answer:0,explain:"Menyadari bahwa desain ini disengaja (bukan kebetulan) membantu kita lebih kritis, bukan menyalahkan diri sendiri karena 'kurang disiplin'.",hint:"Dirancang untuk membuat betah, atau membantu berhenti / kebetulan?"},
{n:23,type:"mcq",micro:"Scroll tanpa akhir",q:"Fitur 'scroll tanpa akhir' (infinite scroll) dirancang agar...",options:["Memberi tanda jelas kapan harus berhenti, sehingga kita tahu persis berapa lama sudah memakai aplikasi","Tidak ada titik alami untuk berhenti, membuat kita terus menggulir tanpa sadar berapa lama","Menghemat kuota pengguna, karena konten muncul bertahap"],answer:1,explain:"Berbeda dari buku/majalah yang punya akhir jelas, scroll tanpa akhir sengaja menghilangkan 'sinyal berhenti alami'.",hint:"Menghilangkan titik berhenti alami, atau memberi titik jelas?"},
{n:24,type:"mcq",micro:"Notifikasi & rasa penasaran",q:"Notifikasi yang terus muncul memanfaatkan rasa penasaran kita karena...",options:["Otak kita tidak tertarik pada hal baru, sehingga notifikasi mudah diabaikan tanpa pengaruh pada pekerjaan","Notifikasi hanya muncul saat istirahat, sehingga tidak mengganggu pekerjaan atau belajar orang yang sibuk","Otak cenderung ingin segera memeriksa hal baru, membuat kita sulit mengabaikannya meski sedang sibuk"],answer:2,explain:"Dorongan 'harus cek sekarang' sering lebih kuat dari kebutuhan sebenarnya untuk melihat notifikasi itu segera.",hint:"Memanfaatkan rasa penasaran otak, atau selalu sangat penting / tak berpengaruh?"},
{n:25,type:"mcq",micro:"FOMO",q:"'FOMO' (fear of missing out / takut ketinggalan) bisa membuat seseorang...",options:["Terus memeriksa media sosial karena takut melewatkan sesuatu yang terjadi di antara teman-temannya","Merasa tenang dan puas, sehingga jarang memeriksa media sosial walau teman sering membagikan kabar","Berhenti memakai media sosial, karena takut ketinggalan justru membuat orang tidak ingin terhubung lagi"],answer:0,explain:"Rasa takut ketinggalan bisa mendorong pemakaian layar yang berlebihan, meski yang 'terlewat' seringnya tidak sepenting yang dirasakan.",hint:"Mendorong terus memeriksa karena takut ketinggalan, atau membuat tenang?"},
{n:26,type:"mcq",micro:"Menghargai kesadaran tanpa menyalahkan diri",q:"Kalau kamu menyadari sulit berhenti scroll, cara pandang yang sehat:",options:["Tanda bahwa kamu lemah dan tidak punya kemauan, jadi kamu harus menyalahkan diri setiap kali sulit berhenti","Ini wajar karena aplikasinya memang dirancang begitu; fokus pada strategi mengelolanya, bukan menyalahkan diri sebagai 'lemah'","Terjadi hanya padamu, bukan pada orang lain, karena orang lain bisa berhenti sesuka hati tanpa usaha"],answer:1,explain:"Memahami bahwa ada desain yang disengaja membuat kita lebih sabar pada diri sendiri & fokus mencari strategi, bukan menyalahkan diri.",hint:"Wajar & fokus strategi, atau menyalahkan diri / pasrah?"},
{n:27,type:"tf",micro:"Aplikasi dirancang oleh tim ahli",q:"Benar atau Salah: Fitur yang membuat aplikasi 'sulit ditinggalkan' muncul secara kebetulan, bukan hasil rancangan yang disengaja.",answer:false,explain:"Sebaliknya, ini bukan kebetulan. Banyak perusahaan mempekerjakan ahli khusus yang mempelajari psikologi perhatian untuk merancang fitur yang memaksimalkan waktu pemakaian.",hint:"Dirancang sengaja oleh ahli, atau kebetulan semata?"},
{n:28,type:"tf",micro:"Mengetahui trik membuat lebih berdaya",q:"Benar atau Salah: Memahami bagaimana aplikasi dirancang menarik perhatian tidak ada gunanya karena tidak mengubah cara kita memakainya.",answer:false,explain:"Sebaliknya, pemahaman ini membuat kita lebih mampu membuat pilihan sadar tentang pemakaian. Tujuannya kesadaran & kendali, bukan otomatis berhenti total.",hint:"Membuat lebih berdaya membuat pilihan, atau tidak ada gunanya?"},
{n:29,type:"mcq",micro:"Auto-play video",q:"Fitur 'putar otomatis' (auto-play) yang langsung memutar video berikutnya tanpa kamu memilih dirancang agar...",options:["Memudahkan kita berhenti dan memilih kegiatan lain, karena setiap video diawali pertanyaan apakah ingin melanjutkan","Menghemat waktu agar kita bisa menonton lebih singkat, sebab pemutaran otomatis membuat kita cepat bosan dan segera menutup aplikasi","Mengurangi 'titik keputusan' di mana kamu bisa memilih berhenti, membuat waktu menonton jadi lebih panjang dari yang direncanakan"],answer:2,explain:"Tanpa harus memilih secara aktif, kita sering 'terseret' menonton lebih lama dari yang sebenarnya diinginkan.",hint:"Mengurangi titik keputusan untuk berhenti, atau membantu berhenti cepat?"},
{n:30,type:"order",micro:"Mengenali & mengatasi pemakaian tak sadar",q:"Urutkan langkah mengenali & mengatasi pemakaian layar yang tidak disadari.",items:["Perhatikan momen 'tiba-tiba sudah lama' scroll tanpa sadar","Sadari fitur apa yang membuatmu sulit berhenti (scroll tanpa akhir, notifikasi, dll)","Matikan/atur fitur itu (mis. matikan auto-play, kurangi notifikasi)","Tetapkan niat sebelum membuka aplikasi: 'aku buka untuk apa & berapa lama'"],answer:[0,1,2,3],explain:"Sadari pola → kenali pemicunya → atur fiturnya → niatkan sebelum membuka. Kesadaran datang sebelum bisa mengubah kebiasaan.",hint:"Mengatur fitur dilakukan sebelum atau sesudah mengenali fitur mana yang jadi pemicu?"},
{n:31,type:"mcq",micro:"Menetapkan niat sebelum membuka aplikasi",q:"Bertanya 'aku buka aplikasi ini untuk apa?' sebelum membukanya membantu karena...",options:["Memberi arah yang jelas, sehingga lebih mudah menyadari saat sudah menyimpang dari tujuan awal & terus scroll tanpa arah","Membuat aplikasi terbuka lebih cepat dan hemat baterai, tanpa ada hubungannya dengan tujuan atau kebiasaan kita memakai aplikasi tersebut","Membuat kita lupa tujuan awal dan terus membuka aplikasi lain"],answer:0,explain:"Niat yang jelas ('cek pesan dari teman') membuat kita lebih sadar saat sudah menyimpang ke scroll tanpa tujuan.",hint:"Memberi arah & kesadaran, atau tak bermanfaat / mengurangi kenikmatan?"},
{n:32,type:"tf",micro:"Notifikasi bisa diatur",q:"Benar atau Salah: Notifikasi hanya bisa diatur semua-nyala atau semua-mati, tidak bisa dipilih per jenis atau per aplikasi.",answer:false,explain:"Sebaliknya, sebagian besar perangkat & aplikasi memungkinkan kita selektif: notifikasi pesan penting tetap aktif, sementara notifikasi 'like' atau promosi bisa dimatikan.",hint:"Bisa diatur selektif, atau harus semua atau tidak sama sekali?"},
{n:33,type:"mcq",micro:"Rasa 'kosong' setelah scroll lama",q:"Perasaan hampa/tidak puas setelah scroll media sosial lama tanpa tujuan sering menjadi tanda bahwa...",options:["Kita sudah terpuaskan sepenuhnya, jadi semakin lama scroll semakin bagus untuk perasaan dan kebutuhan kita dalam kehidupan sehari-hari","Aktivitas itu terasa mengisi waktu tapi tidak benar-benar memuaskan kebutuhan sebenarnya (koneksi nyata, istirahat berkualitas, dll)","Aplikasinya rusak, sehingga perasaan itu tak berhubungan dengan cara kita memakai media sosial"],answer:1,explain:"Mendengarkan perasaan ini adalah petunjuk berharga untuk mengevaluasi apakah aktivitas itu benar-benar memberi yang kita butuhkan.",hint:"Tanda aktivitas tidak memuaskan kebutuhan sebenarnya, atau tanda harus scroll lebih lama?"},
{n:34,type:"mcq",micro:"Perbandingan sosial di media sosial",q:"Melihat unggahan orang lain yang terlihat 'sempurna' (liburan, prestasi) terus-menerus bisa memengaruhi perasaan tentang diri sendiri karena...",options:["Unggahan orang lain menggambarkan kehidupan mereka secara utuh dan jujur, sehingga membandingkan diri dengan mereka akurat dan adil","Melihat unggahan orang lain tidak memengaruhi perasaan, karena otak manusia tidak punya kebiasaan membandingkan","Kita sering membandingkan kehidupan nyata kita (yang biasa-biasa saja) dengan momen terbaik yang dipilih orang lain untuk ditampilkan"],answer:2,explain:"Media sosial sering menampilkan 'sorotan terbaik', bukan kehidupan sehari-hari yang biasa. Membandingkan keduanya bisa menyesatkan.",hint:"Membandingkan hidup nyata dengan sorotan terbaik orang lain, atau semua tampil apa adanya?"},
{n:35,type:"mcq",micro:"Mengatur, bukan menghapus semua",q:"Cara realistis mengelola godaan aplikasi yang menarik perhatian:",options:["Atur batas waktu, kurangi notifikasi, & sadari pemicunya, tanpa harus menghapus semua aplikasi hiburan","Menghapus semua aplikasi hiburan dan menghindari yang menarik, karena itulah cara agar godaan hilang sepenuhnya","Mengandalkan niat saja tanpa mengubah pengaturan perangkat"],answer:0,explain:"Pengelolaan yang seimbang lebih berkelanjutan daripada penghapusan ekstrem yang sulit dipertahankan jangka panjang.",hint:"Atur & kurangi dengan sadar, atau hapus semua / biarkan saja?"},
{n:36,type:"mcq",micro:"Rekomendasi konten & waktu",q:"Algoritma yang merekomendasikan 'video berikutnya yang mungkin kamu suka' terus-menerus dirancang untuk...",options:["Membantu kamu berhenti menonton lebih cepat, dengan konten yang dipilih tidak sesuai minatmu","Membuat kamu terus menonton lebih lama dengan konten yang sangat sesuai minatmu","Menghemat kuota dan baterai, karena rekomendasi dibuat untuk mengurangi pemakaian layar demi kesehatan"],answer:1,explain:"Rekomendasi yang sangat personal & menarik memang efektif membuat kita betah menonton lebih lama dari rencana.",hint:"Membuat betah menonton lama, atau membantu menemukan yang jauh dari minat?"},
{n:37,type:"tf",micro:"Kesadaran akan trik desain membantu memilih",q:"Benar atau Salah: Mengetahui bahwa sebuah fitur dirancang untuk membuat kita terus memakainya sama sekali tidak membantu kita mengambil keputusan yang lebih sadar.",answer:false,explain:"Sebaliknya, pengetahuan ini mengubah kita dari 'terseret otomatis' menjadi 'memilih dengan sadar', meski butuh latihan untuk konsisten.",hint:"Membantu memutuskan secara sadar, atau tidak mengubah apa-apa?"},
{n:38,type:"mcq",micro:"Menyadari waktu yang 'hilang'",q:"Kalimat 'lho, kok udah sejam?' setelah membuka aplikasi 'sebentar saja' menunjukkan...",options:["Aplikasi itu rusak dan jamnya salah, sehingga waktu sebenarnya yang kamu pakai tidak benar-benar sampai sejam seperti yang terlihat","Kamu sadar penuh pada setiap menit pemakaian, jadi tidak ada yang perlu dipelajari atau diubah","Waktu terasa berlalu tanpa disadari saat memakai aplikasi yang dirancang menarik perhatian, sinyal untuk lebih sadar ke depannya"],answer:2,explain:"Pengalaman 'waktu hilang' ini umum & merupakan sinyal berharga untuk membangun kebiasaan yang lebih sadar.",hint:"Sinyal untuk lebih sadar, atau waktu benar-benar berjalan lebih cepat?"},
{n:39,type:"mcq",micro:"Memilih konten dengan sengaja",q:"Mencari & memilih konten tertentu yang ingin ditonton (bukan membiarkan algoritma memutuskan terus-menerus) adalah bentuk...",options:["Mengambil kendali kembali atas pemakaian layar, alih-alih pasif mengikuti rekomendasi tanpa henti","Bentuk pemborosan waktu, karena membiarkan algoritma memutuskan lebih baik daripada memilih sendiri konten tontonan","Kebiasaan yang tak mungkin dilakukan, sebab konten sudah ditentukan penuh"],answer:0,explain:"Memilih dengan sengaja adalah bentuk pemakaian yang lebih aktif & terkendali dibanding mengikuti arus rekomendasi tanpa henti.",hint:"Mengambil kendali kembali, atau tak ada beda / merepotkan?"},
{n:40,type:"open",micro:"Analisis fitur yang membuatmu betah",q:"Pilih satu aplikasi yang menurutmu paling sering membuatmu memakainya lebih lama dari rencana. Analisis: (a) fitur apa yang menurutmu membuatnya 'sulit berhenti' (scroll tanpa akhir, notifikasi, auto-play, rekomendasi personal, dll, sebutkan minimal 2), (b) bagaimana perasaanmu biasanya setelah memakainya lama tanpa rencana, (c) satu perubahan pengaturan konkret yang akan kamu coba untuk mengurangi jebakan itu.",explain:"Jawaban baik: minimal 2 fitur spesifik yang benar-benar ada di aplikasi tersebut (bukan generik), refleksi jujur tentang perasaan setelah pemakaian berlebihan, & satu perubahan pengaturan yang konkret & benar-benar bisa dilakukan (bukan sekadar 'akan lebih disiplin').",hint:"Untuk (a), pikirkan apa yang membuat kamu TIDAK punya titik alami untuk berhenti, itu biasanya fitur kuncinya.",sample:"Aplikasi: aplikasi video pendek yang sering kubuka. (a) Fitur yang membuat sulit berhenti: (1) Scroll ke video berikutnya sangat mudah & cepat (cukup satu gerakan jari), tidak ada jeda atau titik berhenti alami seperti saat menonton satu video utuh di platform lain. (2) Video yang direkomendasikan terasa sangat sesuai minatku, jadi selalu ada 'satu video lagi' yang menarik untuk ditonton, membuatku terus lanjut tanpa sadar. (b) Perasaan setelahnya: biasanya aku merasa sedikit hampa atau menyesal karena waktu terasa 'hilang' begitu saja, & sering aku jadi kurang waktu untuk mengerjakan hal lain yang sebenarnya lebih penting, seperti tugas atau tidur lebih awal. (c) Perubahan yang akan kucoba: aku akan mengatur pengingat waktu di aplikasi itu (banyak aplikasi punya fitur 'istirahat sejenak' setelah durasi tertentu) & menyalakannya, serta memindahkan ikon aplikasi itu ke folder yang tidak langsung terlihat di layar utama, supaya aku harus sengaja mencarinya, bukan membukanya secara refleks."},
{n:41,type:"mcq",micro:"Membuat rencana harian",q:"Cara praktis menjaga keseimbangan setiap hari:",options:["Biarkan semuanya mengalir tanpa rencana, dan lakukan yang terlintas saat itu, karena rencana membuat hari terasa kaku","Rencanakan kapan waktu untuk tugas, layar untuk hiburan, gerak, & tidur, sehingga semuanya punya tempat","Habiskan waktu luang untuk hiburan dulu, baru kerjakan sisanya"],answer:1,explain:"Rencana sederhana (bukan jadwal super ketat) membantu semua kebutuhan penting mendapat tempatnya masing-masing.",hint:"Rencanakan semua kebutuhan penting, atau biarkan tanpa rencana / fokus satu aktivitas?"},
{n:42,type:"mcq",micro:"Zona bebas layar di kamar tidur",q:"Tidak membawa HP ke tempat tidur (atau mengisi dayanya di ruang lain) membantu karena...",options:["Membuat HP lebih lama menyala dan baterai lebih awet, sehingga bisa dipakai lebih banyak di tempat tidur","Membuatmu bisa memeriksa HP sepanjang malam tanpa terganggu orang lain, sehingga kamar jadi tempat bermain layar","Mengurangi godaan memeriksa HP saat seharusnya tidur & menjaga kamar tidur sebagai tempat istirahat"],answer:2,explain:"Kedekatan fisik dengan HP membuat godaan memeriksanya jauh lebih besar, terutama saat sulit tidur.",hint:"Mengurangi godaan & menjaga kamar untuk istirahat, atau tak bermanfaat?"},
{n:43,type:"mcq",micro:"Mengganti kebiasaan, bukan hanya melarang",q:"Alih-alih hanya melarang diri memakai layar, cara yang lebih efektif:",options:["Siapkan alternatif kegiatan yang menarik (buku, olahraga, hobi) untuk mengisi waktu yang biasanya dipakai layar","Larang diri dengan keras dan kosongkan waktu tanpa kegiatan pengganti, sebab waktu kosong mendorong kita melakukan hal berguna","Cukup simpan HP di tempat yang sama dan berharap godaan hilang sendiri"],answer:0,explain:"Larangan tanpa pengganti sering gagal karena waktu kosong itu perlu diisi dengan sesuatu yang juga memuaskan.",hint:"Siapkan alternatif menarik, atau larang tanpa pengganti / rasa bersalah tanpa perubahan?"},
{n:44,type:"mcq",micro:"Mengatur waktu istirahat mata",q:"Aturan '20-20-20' untuk mata (tiap 20 menit, lihat sesuatu sejauh 20 kaki/6 meter selama 20 detik) membantu karena...",options:["Membuat layar lebih terang dan tulisan lebih besar, sehingga mata tak perlu bekerja keras dari jarak dekat","Memberi jeda teratur bagi otot mata yang tegang karena fokus jarak dekat terus-menerus","Menghentikan layar selama sepuluh jam setelahnya agar mata benar-benar beristirahat"],answer:1,explain:"Mengubah fokus jarak secara berkala mengistirahatkan otot mata yang bekerja terus saat menatap layar dekat.",hint:"Memberi jeda otot mata, atau membuat lebih lelah?"},
{n:45,type:"tf",micro:"Pengingat bisa membantu",q:"Benar atau Salah: Menyalakan pengingat/alarm untuk jeda atau berhenti memakai layar tidak berguna karena hanya kemauan pribadi yang menentukan.",answer:false,explain:"Sebaliknya, alarm eksternal bisa membantu saat kesadaran internal belum cukup kuat, terutama saat masih membangun kebiasaan baru, sampai kebiasaan itu terbentuk alami.",hint:"Membantu terutama saat membangun kebiasaan baru, atau tidak berguna?"},
{n:46,type:"mcq",micro:"Menjaga waktu makan bebas layar",q:"Tidak memakai layar saat makan bersama keluarga/teman membantu karena...",options:["Membuat makanan lebih cepat dingin dan kurang enak, sehingga tak bermanfaat bagi hubungan dengan keluarga atau teman","Mengurangi kesempatan mengobrol karena kita bingung harus berbicara apa, sehingga layar sebaiknya tetap dipegang","Memberi ruang untuk mengobrol & terhubung, yang mudah terlewat kalau perhatian terbagi ke layar"],answer:2,explain:"Waktu makan bersama adalah kesempatan alami untuk terhubung yang sayang dilewatkan karena sibuk dengan layar.",hint:"Memberi ruang mengobrol & terhubung, atau tak berhubungan dengan sosial?"},
{n:47,type:"mcq",micro:"Menetapkan batas waktu aplikasi",q:"Fitur 'batas waktu aplikasi' yang memberi peringatan setelah durasi tertentu berguna karena...",options:["Memberi kesempatan untuk berhenti sejenak & memutuskan sadar apakah ingin lanjut, bukan otomatis terus tanpa jeda","Menghukum kita agar tak bisa memakai aplikasi lagi seumur hidup, bukan memberi kesempatan berhenti dan memutuskan sadar","Membuat kita lebih lama memakai aplikasi karena peringatannya diabaikan, sehingga fitur ini sebaiknya dimatikan"],answer:0,explain:"Peringatan ini bukan penjara, tapi titik refleksi untuk memutuskan dengan sadar, bukan otomatis melanjutkan tanpa berpikir.",hint:"Titik refleksi untuk memutuskan sadar, atau memaksa / tak berguna?"},
{n:48,type:"mcq",micro:"Mengisi waktu senggang dengan variasi",q:"Punya beberapa pilihan kegiatan non-layar yang disukai (olahraga, membaca, menggambar, main dengan hewan peliharaan) membantu karena...",options:["Membuat kita makin bingung memilih kegiatan, sehingga akhirnya memilih layar karena itulah yang terasa mudah dilakukan","Memudahkan memilih alternatif saat ingin istirahat dari layar, daripada bingung & akhirnya kembali ke layar karena tidak ada pilihan lain","Tidak ada gunanya, sebab kegiatan non-layar membosankan dan tak bisa menggantikan kesenangan dari layar hiburan"],answer:1,explain:"Variasi pilihan yang sudah siap membuat lebih mudah memilih non-layar saat ingin istirahat dari layar.",hint:"Memudahkan memilih alternatif, atau tak bermanfaat / merumitkan?"},
{n:49,type:"mcq",micro:"Menyusun rutinitas sebelum tidur",q:"Rutinitas sebelum tidur yang tidak melibatkan layar (mis. membaca, mendengarkan musik tenang, journaling) membantu karena...",options:["Membuat tubuh dan pikiran makin segar dan bersemangat, sehingga tidur menjadi lebih lambat tetapi lebih nyenyak daripada saat memakai layar","Tidak ada pengaruhnya pada tidur, sebab rutinitas sebelum tidur hanya kebiasaan kosong","Memberi sinyal pada tubuh & pikiran bahwa waktunya beristirahat, tanpa rangsangan layar yang membuat tetap 'terjaga'"],answer:2,explain:"Rutinitas yang tenang & konsisten membantu tubuh mengenali 'saatnya tidur' secara alami.",hint:"Membantu tubuh siap istirahat, atau tak berpengaruh / mempersulit?"},
{n:50,type:"order",micro:"Membangun kebiasaan bebas layar sebelum tidur",q:"Urutkan langkah membangun kebiasaan bebas layar sebelum tidur.",items:["Tentukan waktu (mis. 30-60 menit sebelum tidur) untuk berhenti memakai layar","Siapkan pengingat/alarm untuk waktu itu","Siapkan aktivitas pengganti yang tenang (baca buku, ngobrol, dll)","Letakkan HP di luar jangkauan mudah (ruang lain/laci) selama waktu itu"],answer:[0,1,2,3],explain:"Tentukan waktu → siapkan pengingat → siapkan pengganti → jauhkan HP secara fisik. Menjauhkan HP secara fisik memperkuat kebiasaan yang sudah direncanakan.",hint:"Menjauhkan HP secara fisik dilakukan setelah menyiapkan aktivitas pengganti, atau di awal tanpa persiapan lain?"},
{n:51,type:"mcq",micro:"Menyeimbangkan game & aktivitas lain",q:"Menikmati bermain game dalam waktu yang direncanakan (bukan tanpa batas) berarti...",options:["Menetapkan durasi/waktu tertentu untuk bermain, lalu berhenti sesuai rencana, meski game-nya masih terasa seru","Bermain sepuasnya tanpa batas waktu sampai bosan sendiri, lalu berhenti hanya ketika baterai habis atau ada orang yang menyuruh berhenti","Tidak bermain game lagi seumur hidup agar tak ada risiko, karena bermain game merugikan banyak orang"],answer:0,explain:"Menikmati dengan batas yang direncanakan berbeda dari 'sampai bosan', yang seringkali sangat lama karena game dirancang menarik.",hint:"Bermain sesuai rencana lalu berhenti, atau sampai bosan tanpa batas / tak boleh main?"},
{n:52,type:"tf",micro:"Keluarga bisa membuat kesepakatan bersama",q:"Benar atau Salah: Tidak ada bedanya antara aturan waktu layar yang disepakati bersama keluarga dengan aturan sepihak yang hanya berlaku untuk anak.",answer:false,explain:"Sebaliknya, kesepakatan bersama (termasuk orang dewasa mengikuti aturan serupa) terasa lebih adil, lebih mudah dijalankan bersama, & memberi contoh nyata.",hint:"Lebih adil & mudah dijalankan bersama, atau tidak ada bedanya?"},
{n:53,type:"mcq",micro:"Mengganti scroll dengan aktivitas kreatif",q:"Mengganti sebagian waktu scroll pasif dengan aktivitas kreatif di layar (menggambar digital, menulis, edit video) adalah cara...",options:["Menambah total waktu layar sebanyak mungkin tanpa memedulikan isinya, sehingga hasilnya sama dengan membuka media sosial tanpa tujuan","Tetap memakai layar tapi dengan cara yang lebih aktif & memuaskan, bukan sekadar mengurangi waktu layar total","Mengganti semua kegiatan non-layar dengan layar kreatif, sehingga tak perlu bergerak"],answer:1,explain:"Keseimbangan bukan hanya soal jumlah waktu, tapi juga kualitas & jenis aktivitas yang dilakukan dengan layar.",hint:"Mengganti dengan aktivitas aktif yang memuaskan, atau sama saja / selalu lebih buruk?"},
{n:54,type:"mcq",micro:"Menyadari pemicu emosional",q:"Kalau kamu sering membuka HP saat merasa bosan/sedih/cemas, menyadari pola ini membantu karena...",options:["Kamu bisa makin sering membuka HP setiap kali merasa tidak enak, sebab layar adalah cara terbaik menangani perasaan","Perasaan itu hilang sendiri setelah kamu membuka HP, jadi tak perlu mencari cara lain atau bercerita pada orang lain","Kamu bisa mencari cara lain menangani perasaan itu, bukan selalu mengandalkan layar sebagai pelarian otomatis"],answer:2,explain:"Menyadari pemicu emosional membuka pilihan: apakah layar benar-benar membantu perasaan itu, atau ada cara lain yang lebih membantu.",hint:"Membuka pilihan cara lain menangani perasaan, atau tak berguna / harus terus begitu?"},
{n:55,type:"mcq",micro:"Merencanakan liburan/waktu luang panjang",q:"Saat liburan panjang tanpa jadwal sekolah, tetap membuat rencana sederhana (kapan layar, kapan aktivitas lain) membantu karena...",options:["Mencegah waktu luang panjang habis sepenuhnya untuk layar tanpa disadari","Tidak perlu direncanakan karena liburan waktunya bebas sepenuhnya","Membuat liburan jadi terasa seperti sekolah"],answer:0,explain:"Tanpa struktur sekolah, waktu luang panjang sangat rentan habis untuk layar tanpa terasa. Rencana sederhana membantu menjaga keseimbangan.",hint:"Mencegah waktu habis untuk layar, atau tak perlu direncanakan?"},
{n:56,type:"tf",micro:"Kebiasaan kecil menumpuk jadi besar",q:"Benar atau Salah: Perubahan drastis yang langsung besar selalu lebih efektif jangka panjang daripada perubahan kecil yang konsisten.",answer:false,explain:"Sebaliknya, perubahan kecil & konsisten (mis. berhenti 30 menit lebih awal tiap malam) lebih mudah bertahan & bisa berdampak besar jangka panjang, sementara perubahan drastis sering gagal karena terlalu berat dijalani terus-menerus.",hint:"Perubahan kecil konsisten lebih efektif jangka panjang, atau perubahan drastis selalu lebih baik?"},
{n:57,type:"mcq",micro:"Menjaga keseimbangan saat belajar daring",q:"Saat harus belajar lewat layar (kelas daring, tugas digital), cara menjaga keseimbangan tetap terjaga:",options:["Pakai layar terus sampai tugas selesai tanpa jeda, lalu lanjutkan hiburan di layar sampai malam, karena belajar daring itu wajar","Tetap sisipkan jeda, & pastikan waktu di luar keperluan belajar tidak semuanya juga dihabiskan di layar","Hindari kegiatan lain di luar layar saat belajar daring, supaya fokus terjaga"],answer:1,explain:"Kalau belajar sudah banyak memakai layar, penting menjaga waktu luang diisi dengan hal non-layar agar tetap seimbang secara keseluruhan.",hint:"Jaga jeda & imbangi dengan non-layar, atau anggap sama saja / tambah hiburan sebanding?"},
{n:58,type:"mcq",micro:"Menghargai progres kecil",q:"Kalau kamu berhasil mengurangi waktu layar sedikit dari biasanya (meski belum sempurna), sikap yang membangun:",options:["Abaikan kemajuan itu karena belum sempurna, lalu tuntut dirimu langsung berhasil besok, kalau tidak berarti gagal total","Anggap sudah cukup dan berhenti berusaha, karena sedikit pengurangan sudah cukup","Hargai progres kecil itu sebagai langkah maju, bukan menuntut kesempurnaan instan"],answer:2,explain:"Perubahan kebiasaan butuh waktu. Menghargai progres kecil menjaga motivasi untuk terus memperbaiki diri.",hint:"Hargai progres kecil, atau anggap tak berarti / menyerah?"},
{n:59,type:"mcq",micro:"Melibatkan teman dalam perubahan kebiasaan",q:"Mengajak teman untuk sama-sama mengurangi scroll berlebihan (mis. saat kumpul bersama, sepakat menyimpan HP) membantu karena...",options:["Dukungan sosial membuat perubahan kebiasaan lebih mudah dijalani bersama daripada sendirian","Membuat perubahan lebih sulit, karena teman cenderung menertawakan usaha kita, sehingga lebih baik berusaha sendiri","Tidak berpengaruh, sebab kebiasaan layar hanya ditentukan diri sendiri"],answer:0,explain:"Perubahan kebiasaan lebih mudah bertahan dengan dukungan sosial, dilakukan bersama daripada sendirian melawan godaan.",hint:"Dukungan sosial memudahkan, atau tak berguna / membuat teman menjauh?"},
{n:60,type:"open",micro:"Rancang rencana keseimbangan pribadi",q:"Buat rencana keseimbangan layar pribadi untuk 2 minggu ke depan. Sertakan: (a) satu 'zona/waktu bebas layar' yang akan kamu terapkan, (b) 2 aktivitas pengganti yang sudah kamu siapkan untuk mengisi waktu itu, (c) satu pengaturan teknis yang akan kamu ubah (notifikasi, batas waktu aplikasi, dll), (d) bagaimana kamu akan mengukur apakah rencana ini berhasil setelah 2 minggu.",explain:"Jawaban baik: zona/waktu yang spesifik & realistis, 2 aktivitas pengganti konkret yang sudah 'disiapkan' bukan sekadar ide, pengaturan teknis yang benar-benar bisa dilakukan di perangkat, & cara mengukur yang bisa diperiksa dengan data/pengamatan nyata (bukan sekadar 'merasa lebih baik').",hint:"Bagian (d) sebaiknya menyertakan cara yang bisa diukur dengan angka (data waktu layar, jam tidur), bukan hanya perasaan subjektif.",sample:"(a) Zona/waktu bebas layar: 45 menit sebelum tidur (dari jam 21.15 sampai jam 22.00), & saat makan malam bersama keluarga. (b) Aktivitas pengganti: (1) Membaca buku fiksi yang sudah lama ingin kubaca, kusiapkan di meja dekat tempat tidur supaya mudah diambil. (2) Mengobrol dengan keluarga atau menulis jurnal singkat tentang hari itu. (c) Pengaturan teknis: mematikan semua notifikasi kecuali pesan langsung dari kontak dekat, & mengaktifkan fitur pengingat waktu di aplikasi media sosial supaya muncul peringatan setelah 45 menit pemakaian per hari. (d) Mengukur keberhasilan: setelah 2 minggu, aku akan mengecek data waktu layar di HP untuk membandingkan dengan sebelumnya (targetku turun minimal 20% untuk kategori hiburan), mencatat apakah aku benar-benar tidur lebih awal dari biasanya (targetnya sebelum jam 22.30), & bertanya pada diriku apakah aku merasa lebih segar & punya lebih banyak waktu untuk hal lain yang kusukai."},
{n:61,type:"mcq",micro:"Kebiasaan berlebihan vs kecanduan",q:"Beda 'kebiasaan yang perlu diperbaiki' dengan tanda yang lebih serius (kecanduan) biasanya terlihat dari...",options:["Berapa banyak aplikasi yang terpasang di perangkat, sebab makin banyak aplikasi makin parah kecanduannya, tanpa melihat pengaruhnya pada kehidupan sehari-hari","Apakah orang itu masih bisa mengendalikan pemakaiannya & tidak sangat terganggu fungsinya (sekolah, tidur, hubungan), atau sudah kesulitan besar mengendalikannya meski ingin","Warna layar dan merek perangkat yang dipakai, karena kecanduan layar hanya ditentukan oleh jenis perangkat dan bukan oleh perilaku pemakainya"],answer:1,explain:"Kebiasaan yang perlu diperbaiki masih dalam kendali; ketika seseorang benar-benar tidak bisa mengendalikannya meski sangat ingin, & itu merusak fungsi penting hidupnya, itu tanda yang lebih serius.",hint:"Kemampuan mengendalikan & dampak pada fungsi hidup, atau hanya soal jumlah jam?"},
{n:62,type:"mcq",micro:"Tanda yang perlu diperhatikan lebih serius",q:"Tanda yang layak mendapat perhatian & mungkin butuh bantuan lebih (bukan sekadar 'kurangi sedikit'):",options:["Sesekali merasa bosan dan ingin mencoba kegiatan lain setelah lama memakai layar, tetapi tetap makan, tidur, dan belajar seperti biasa tanpa gangguan","Menikmati layar sebentar setiap hari dengan tenang, bisa berhenti kapan pun saat diminta, dan nilai serta hubungan dengan keluarga tetap baik","Sangat gelisah/marah saat tidak bisa memakai layar, mengabaikan kebutuhan dasar (makan, tidur, kebersihan) demi layar, atau hubungan & prestasi memburuk drastis karenanya"],answer:2,explain:"Tanda yang lebih serius melibatkan gangguan fungsi dasar & reaksi emosional yang kuat, bukan sekadar menikmati hiburan secukupnya.",hint:"Gangguan fungsi dasar & reaksi kuat, atau sesekali lupa waktu / menikmati secukupnya?"},
{n:63,type:"mcq",micro:"Kapan bicara ke orang dewasa",q:"Kalau kamu merasa sulit mengendalikan waktu layar meski sudah mencoba berbagai cara, & itu mulai mengganggu tidur/sekolah/hubunganmu, langkah yang bijak:",options:["Bicara dengan orang tua/wali atau konselor sekolah untuk mencari bantuan bersama, bukan mencoba menanganinya sendirian terus-menerus","Simpan sendiri dan jangan memberi tahu orang lain, lalu coba cara yang sama berulang tanpa bantuan, karena minta bantuan berarti lemah","Menunggu sampai masalahnya hilang sendiri tanpa mengubah apa-apa, sebab kebiasaan memakai layar otomatis berkurang seiring waktu"],answer:0,explain:"Meminta bantuan saat sesuatu terasa di luar kendali adalah langkah bijak, bukan tanda kegagalan.",hint:"Bicara & cari bantuan bersama, atau sembunyikan / anggap wajar?"},
{n:64,type:"tf",micro:"Meminta bantuan bukan tanda gagal",q:"Benar atau Salah: Meminta bantuan orang dewasa untuk mengelola kebiasaan layar yang terasa sulit dikendalikan adalah langkah yang bijak, bukan tanda kegagalan pribadi.",answer:true,explain:"Sama seperti keterampilan lain, kadang kita butuh dukungan orang lain untuk membangun kebiasaan yang lebih sehat.",hint:"Langkah bijak, atau tanda gagal?"},
{n:65,type:"mcq",micro:"Perbedaan individu",q:"Sebagian orang lebih mudah 'terseret' pemakaian layar berlebihan dibanding yang lain karena...",options:["Semua orang punya kerentanan yang persis sama, sehingga tak ada yang lebih mudah terseret dibanding orang lain","Perbedaan kepribadian, kebutuhan emosional saat itu, & jenis konten yang mereka konsumsi bisa membuat sebagian orang lebih rentan","Hanya orang yang bodoh atau malas yang bisa terseret, sebab orang pintar dan rajin tidak mungkin tertarik pada layar secara berlebihan"],answer:1,explain:"Memahami perbedaan individu membantu kita tidak menghakimi diri sendiri atau orang lain terlalu keras, & mencari strategi yang sesuai kebutuhan masing-masing.",hint:"Ada faktor kepribadian & konteks, atau semua sama / hanya soal kemauan?"},
{n:66,type:"mcq",micro:"Menyeimbangkan tanpa menghakimi orang lain",q:"Melihat teman menghabiskan banyak waktu di layar, sikap yang lebih membantu daripada menghakimi:",options:["Menceramahinya panjang lebar di depan banyak orang agar ia malu dan segera berhenti, sebab teguran keras paling ampuh","Menertawakannya dan menyebarkan kebiasaannya sebagai bahan olok-olok, supaya ia terdorong mengurangi waktu layarnya","Tanyakan dengan peduli bagaimana perasaannya tentang kebiasaannya sendiri, tanpa menceramahi atau merendahkan"],answer:2,explain:"Kepedulian yang tulus & tidak menghakimi lebih mungkin membuka percakapan yang membantu daripada ejekan atau ceramah.",hint:"Tanya dengan peduli tanpa menghakimi, atau mengejek / abaikan?"},
{n:67,type:"mcq",micro:"Keseimbangan berubah seiring situasi",q:"Keseimbangan waktu layar yang wajar bisa berbeda saat masa ujian dibanding masa liburan karena...",options:["Kebutuhan & prioritas berubah sesuai situasi; yang penting prinsip dasarnya (tidur cukup, gerak, hubungan) tetap terjaga","Aturan keseimbangan layar tidak berubah, sehingga masa ujian dan liburan harus diperlakukan dengan cara yang sama","Saat ujian kita boleh mengabaikan tidur dan gerak demi layar, sedangkan saat liburan semua prinsip kesehatan boleh dilupakan"],answer:0,explain:"Fleksibilitas dalam menerapkan prinsip (bukan aturan kaku) membuat keseimbangan lebih realistis untuk berbagai situasi hidup.",hint:"Bisa berbeda sesuai situasi tapi prinsip tetap, atau selalu sama persis / sebanyak mungkin saat ujian?"},
{n:68,type:"tf",micro:"Tidak ada 'nol waktu layar' yang realistis",q:"Benar atau Salah: Di dunia sekarang, tujuan yang realistis biasanya bukan 'nol waktu layar', melainkan pemakaian yang seimbang & sadar, karena layar juga dipakai untuk belajar, bekerja, & terhubung.",answer:true,explain:"Layar adalah bagian nyata dari kehidupan modern (sekolah, kerja, komunikasi). Tujuannya keseimbangan, bukan penghindaran total yang tidak realistis.",hint:"Tujuan realistis adalah keseimbangan, atau nol waktu layar sama sekali?"},
{n:69,type:"mcq",micro:"Menyeimbangkan rasa senang & tanggung jawab",q:"Menikmati waktu layar untuk hiburan TIDAK perlu selalu dirasa bersalah, selama...",options:["Kamu sudah memakai layar lebih lama dari teman-temanmu, karena yang penting adalah menang dalam lomba siapa yang paling lama memakai perangkat","Tanggung jawab lain (tugas, tidur, kesehatan) sudah terpenuhi & waktunya memang direncanakan, bukan menggantikan hal penting","Tugas, tidur, dan kesehatanmu dikorbankan demi layar, selama kamu merasa senang saat memainkannya"],answer:1,explain:"Hiburan yang seimbang & terencana adalah bagian sehat dari hidup, bukan sesuatu yang harus selalu ditebus dengan rasa bersalah.",hint:"Tidak perlu bersalah selama tanggung jawab terpenuhi, atau selalu bersalah / tak berhubungan?"},
{n:70,type:"tf",micro:"Kesadaran diri berkembang seiring waktu",q:"Benar atau Salah: Kemampuan mengenali & mengelola kebiasaan layar sendiri adalah keterampilan yang terus berkembang seiring usia & pengalaman, bukan sesuatu yang harus langsung sempurna.",answer:true,explain:"Wajar mengalami pasang surut dalam mengelola kebiasaan ini. Yang penting terus belajar & memperbaiki, bukan menuntut kesempurnaan instan.",hint:"Terus berkembang & wajar tidak sempurna, atau harus langsung sempurna?"},
{n:71,type:"mcq",micro:"Menilai kualitas waktu, bukan hanya kuantitas",q:"Selain 'berapa lama', pertanyaan yang juga penting tentang waktu layar:",options:["'Berapa banyak orang lain yang memakai layar lebih lama dariku hari ini, supaya aku merasa lebih baik?' tanpa memikirkan manfaatnya","'Apakah layarku lebih terang daripada layar milik temanku?' tanpa memikirkan manfaat atau kepuasan yang kudapat","'Apakah waktu ini benar-benar bermanfaat/menyenangkan bagiku, atau hanya kebiasaan otomatis tanpa kepuasan nyata?'"],answer:2,explain:"Kualitas & kesadaran pemakaian sama pentingnya dengan jumlah waktu. Dua jam yang disengaja & memuaskan berbeda dari dua jam yang otomatis & hampa.",hint:"Tanyakan kebermanfaatan & kepuasan, atau hanya durasi?"},
{n:72,type:"mcq",micro:"Perbedaan pemakaian untuk koneksi vs pelarian",q:"Memakai layar untuk terhubung dengan teman jauh (video call, chat) berbeda dari memakainya untuk...",options:["Menghindari perasaan sulit atau situasi yang seharusnya dihadapi langsung, karena tujuan & dampaknya berbeda","Berbicara dengan keluarga dan teman dekat secara langsung, sebab tujuannya sama dan tak ada bedanya dari sisi dampak","Mengerjakan tugas sekolah dan belajar hal baru, karena kedua kegiatan itu bertujuan menghindari perasaan sulit"],answer:0,explain:"Tujuan pemakaian (menghubungkan vs menghindar) memengaruhi apakah itu memperkaya hidup atau justru menghindarkan kita dari hal yang perlu dihadapi.",hint:"Beda tujuan, terhubung vs menghindar, atau sama saja / selalu buruk?"},
{n:73,type:"mcq",micro:"Keseimbangan sebagai keterampilan hidup",q:"Belajar mengelola waktu layar sekarang berguna untuk masa depan karena...",options:["Teknologi hanya ada pada masa kini dan akan hilang di masa depan, jadi keterampilan ini tak berguna setelah dewasa","Godaan & teknologi baru akan terus ada seumur hidup; keterampilan mengelola diri ini akan terus relevan","Godaan layar berhenti sendiri ketika dewasa, sehingga tak perlu belajar sekarang"],answer:1,explain:"Keterampilan mengelola perhatian & waktu di dunia digital akan terus dibutuhkan seiring teknologi terus berkembang.",hint:"Terus relevan seumur hidup, atau hanya saat sekolah / teknologi akan berhenti?"},
{n:74,type:"mcq",micro:"Menghadapi kekambuhan kebiasaan lama",q:"Kalau setelah beberapa minggu berhasil, kamu kembali ke kebiasaan lama (scroll berlebihan lagi), sikap yang membantu:",options:["Menyalahkan diri sepenuhnya dan menyerah, karena gagal sekali berarti kamu memang tidak mampu mengubah kebiasaan","Pura-pura tidak terjadi apa-apa dan jangan mengevaluasi, sebab melihat kembali kegagalan membuatmu sedih dan hilang semangat","Anggap sebagai bagian normal dari proses, evaluasi apa yang berubah, & coba lagi tanpa menyerah sepenuhnya"],answer:2,explain:"Perubahan kebiasaan jarang linear. Kembali sesekali ke pola lama adalah hal biasa; yang penting terus mencoba & belajar dari itu.",hint:"Anggap normal & coba lagi, atau anggap sia-sia / hukum diri?"},
{n:75,type:"order",micro:"Menilai apakah butuh bantuan lebih",q:"Urutkan langkah menilai apakah kebiasaan layarmu butuh bantuan lebih dari sekadar strategi mandiri.",items:["Perhatikan apakah kamu sudah mencoba strategi mandiri (batas waktu, zona bebas layar) tapi masih sangat kesulitan","Perhatikan dampaknya pada tidur, sekolah, kesehatan, & hubunganmu","Perhatikan reaksi emosionalmu saat tidak bisa memakai layar (sangat marah/cemas berlebihan)","Bila salah satu tanda serius muncul, bicarakan dengan orang dewasa tepercaya untuk mencari bantuan bersama"],answer:[0,1,2,3],explain:"Coba strategi mandiri dulu → perhatikan dampak fungsi hidup → perhatikan reaksi emosional → bicara ke dewasa bila ada tanda serius. Menilai bertahap sebelum memutuskan perlu bantuan tambahan.",hint:"Berbicara ke orang dewasa dilakukan di awal atau setelah menilai tanda-tanda yang muncul?"},
{n:76,type:"tf",micro:"Bantuan tersedia & bisa membantu",q:"Benar atau Salah: Ada berbagai bentuk dukungan (keluarga, sekolah, konselor) yang bisa membantu seseorang membangun keseimbangan layar yang lebih sehat bila dibutuhkan.",answer:true,explain:"Tidak perlu menghadapi kesulitan ini sendirian. Dukungan dari berbagai pihak tersedia & bisa sangat membantu.",hint:"Ada dukungan yang tersedia, atau harus dihadapi sendirian?"},
{n:77,type:"mcq",micro:"Menyeimbangkan tanpa ekstrem",q:"Pendekatan yang lebih berkelanjutan untuk keseimbangan layar:",options:["Perubahan bertahap & realistis yang bisa dipertahankan jangka panjang, bukan aturan sangat ketat yang mudah menyerah di tengah jalan","Aturan yang sangat ketat dan sulit sejak hari pertama, supaya kamu langsung berhasil sempurna dan tak perlu mengubah lagi","Perubahan besar dalam sehari yang dipaksakan tanpa rencana, karena perubahan mendadak lebih mudah dipertahankan daripada bertahap"],answer:0,explain:"Perubahan drastis sering tidak bertahan lama. Langkah bertahap yang realistis lebih mungkin menjadi kebiasaan yang benar-benar melekat.",hint:"Bertahap & realistis, atau sangat ketat / tanpa perubahan?"},
{n:78,type:"mcq",micro:"Refleksi rutin",q:"Meluangkan waktu sesekali (mis. mingguan) untuk merefleksikan pola pemakaian layar membantu karena...",options:["Kebiasaan tidak berubah, sehingga cukup diperiksa sekali seumur hidup lalu tak perlu direnungkan lagi","Kebiasaan bisa berubah seiring waktu tanpa disadari; refleksi rutin membantu tetap sadar & menyesuaikan bila perlu","Refleksi hanya membuang waktu dan membuat kita merasa bersalah, sehingga lebih baik dihindari dan kebiasaan dibiarkan"],answer:1,explain:"Kebiasaan bisa perlahan bergeser tanpa disadari. Memeriksa secara berkala menjaga kesadaran tetap terjaga dari waktu ke waktu.",hint:"Membantu tetap sadar & menyesuaikan, atau tak perlu / terlalu memikirkan hal kecil?"},
{n:79,type:"mcq",micro:"Keseimbangan sebagai pilihan berulang",q:"Menjaga keseimbangan layar lebih tepat dipahami sebagai...",options:["Satu keputusan besar yang cukup dibuat sekali lalu selesai, tanpa perlu memikirkan atau menyesuaikannya lagi","Hal yang hanya bergantung pada keberuntungan atau kemauan orang lain di sekitar kita, sehingga tidak bisa dipengaruhi oleh pilihan kita sendiri","Serangkaian pilihan kecil yang dibuat berulang kali sepanjang waktu, bukan satu keputusan besar yang selesai sekali untuk selamanya"],answer:2,explain:"Setiap hari membawa pilihan baru (buka aplikasi ini atau tidak, lanjut atau berhenti). Keseimbangan dijaga lewat pilihan-pilihan kecil yang berulang.",hint:"Pilihan berulang sepanjang waktu, atau satu keputusan sekali selesai / otomatis?"},
{n:80,type:"open",micro:"Membedakan kebiasaan & tanda serius",q:"Bayangkan seorang teman: setiap kali HP-nya diambil sebentar (mis. saat ujian), ia sangat gelisah & marah; ia sering begadang sampai larut bermain game hingga mengantuk parah di kelas & nilainya turun drastis; ia juga mulai jarang bertemu teman lama karena memilih di kamar dengan HP. Analisis: (a) apakah ini masih 'kebiasaan yang perlu diperbaiki' atau sudah tanda yang lebih serius, jelaskan dengan menyebut tanda spesifik, (b) apa yang kamu lakukan sebagai teman, (c) kenapa penting melibatkan orang dewasa, bukan menyelesaikannya sendiri sebagai teman sebaya.",explain:"Jawaban baik: identifikasi yang tepat sebagai tanda serius (bukan sekadar kebiasaan) dengan menyebut MINIMAL 3 tanda spesifik dari cerita (reaksi emosional kuat, dampak fungsi nyata, penarikan sosial), rencana sebagai teman yang suportif & realistis (bukan mengambil alih peran profesional), & penjelasan yang jelas kenapa melibatkan orang dewasa penting & bukan tanda 'mengkhianati' temannya.",hint:"Bagian (a) harus menyebut tanda SPESIFIK dari cerita (bukan kesimpulan umum), & bagian (c) harus menjelaskan batas kemampuan teman sebaya, bukan hanya 'karena orang dewasa lebih berpengalaman'.",sample:"(a) Ini sudah masuk tanda yang lebih serius, bukan sekadar kebiasaan yang perlu sedikit diperbaiki. Tanda spesifiknya: (1) Reaksi emosional yang kuat (sangat gelisah & marah) saat tidak bisa memakai HP, menunjukkan kesulitan mengendalikan diri, bukan sekadar tidak suka. (2) Dampak nyata pada fungsi penting: nilai turun drastis & sering mengantuk di kelas, berarti prestasi & kesehatan (tidur) sudah terganggu serius, bukan hanya sesekali. (3) Menarik diri dari hubungan sosial nyata (jarang bertemu teman lama), yang bisa jadi tanda ia menggantikan koneksi nyata dengan layar, bukan sekadar menikmati hiburan seimbang. Ketiga hal ini bersamaan (bukan hanya satu) menunjukkan pola yang lebih dari sekadar 'kebiasaan biasa'. (b) Sebagai teman: aku akan tetap berusaha menjaga hubungan dengannya (mengajak ngobrol, sesekali mengajak kegiatan bersama tanpa memaksa), mendengarkan tanpa menghakimi bila ia mau cerita, & mendorongnya (dengan lembut, bukan menuduh) untuk bicara dengan orang tua atau konselor sekolah, mungkin dengan menawarkan menemaninya bila ia merasa takut/malu melakukannya sendiri. (c) Penting melibatkan orang dewasa karena: situasi ini menyangkut kesehatan (tidur, mungkin lebih dalam) & prestasi akademik yang butuh penanganan yang lebih dari sekadar dukungan teman sebaya; orang dewasa (orang tua, konselor) punya akses ke sumber daya & keahlian untuk membantu secara lebih menyeluruh, & sebagai teman sebaya aku tidak punya kapasitas atau wewenang untuk menangani hal seserius ini sendirian, aku bisa mendukung, tapi bukan menggantikan bantuan profesional/orang dewasa yang tepat."},
{n:81,type:"mcq",micro:"Skenario: godaan saat mengerjakan tugas",q:"Saat mengerjakan tugas di laptop, notifikasi media sosial terus muncul & menggodamu untuk membuka. Cara mengatasi:",options:["Matikan notifikasi sementara atau gunakan mode fokus selama mengerjakan tugas, buka lagi setelah selesai","Biarkan notifikasi menyala sepanjang waktu dan sesekali membukanya sambil mengerjakan tugas, karena itu cara paling efisien membagi perhatian","Hapus semua aplikasi media sosial agar tak ada godaan, walau masih kamu butuhkan"],answer:0,explain:"Mematikan sumber gangguan selama waktu fokus jauh lebih efektif daripada mencoba menahan diri setiap kali godaan muncul.",hint:"Matikan sumber gangguan selama fokus, atau buka sebentar tiap kali / biarkan terus?"},
{n:82,type:"mcq",micro:"Skenario: keluarga ingin waktu bersama tanpa layar",q:"Keluargamu mengusulkan 'malam tanpa layar' seminggu sekali untuk main board game/mengobrol bersama, tapi kamu merasa akan bosan. Sikap yang terbuka:",options:["Langsung menolak dan tidak ikut, karena yakin akan bosan, sehingga kamu tak perlu mencoba atau mengetahui rasanya","Coba dulu dengan pikiran terbuka; banyak orang menemukan momen semacam ini lebih berkesan dari dugaan awal","Ikut dengan terpaksa sambil memegang HP sepanjang malam, sehingga kegiatan keluarga tak memberi manfaat bagimu"],answer:1,explain:"Memberi kesempatan mencoba sebelum menolak membuka peluang menemukan pengalaman positif yang tidak terduga.",hint:"Coba dengan terbuka, atau menolak / diam-diam bawa HP?"},
{n:83,type:"mcq",micro:"Skenario: game yang dirancang sulit berhenti",q:"Sebuah game punya sistem 'hadiah harian' yang membuatmu merasa harus masuk setiap hari agar tidak 'rugi'. Cara menyikapinya:",options:["Masuk setiap hari tanpa berpikir, karena kalau tidak masuk kamu rugi besar dan semua usahamu sia-sia","Menganggap sistem itu tidak ada sangkut pautnya dengan rasa takut rugi, sebab hadiah harian dibuat hanya untuk berbuat baik kepada para pemainnya","Sadari itu adalah desain yang sengaja memanfaatkan rasa takut rugi (FOMO); putuskan dengan sadar apakah benar-benar ingin ikut pola itu atau tidak"],answer:2,explain:"Mengenali taktik desain ini memberi kendali untuk memilih dengan sadar, bukan otomatis mengikuti dorongan yang dirancang.",hint:"Sadari desainnya & putuskan sadar, atau ikuti otomatis / berhenti tanpa evaluasi?"},
{n:84,type:"mcq",micro:"Skenario: perbandingan dengan teman di media sosial",q:"Kamu merasa buruk setelah melihat unggahan liburan mewah teman-teman di media sosial. Cara menyikapi perasaan itu:",options:["Ingatkan diri bahwa media sosial sering hanya menampilkan momen terbaik, bukan gambaran utuh kehidupan seseorang, & pertimbangkan mengurangi pemakaian yang memicu perasaan itu","Mulai membeli barang dan merencanakan liburan serupa meski tidak mampu, agar bisa mengunggah momen yang sama persis dan merasa setara dengan mereka","Menganggap unggahan itu gambaran utuh kehidupan mereka dan menyimpulkan hidupmu jauh lebih buruk dibanding teman"],answer:0,explain:"Menyadari sifat 'sorotan terbaik' media sosial & mengelola pemakaian yang memicu perbandingan tidak sehat adalah respons yang bijak.",hint:"Ingatkan realita & kurangi pemicu, atau percaya penuh / terus scroll?"},
{n:85,type:"tf",micro:"Keseimbangan bisa dinikmati, bukan hanya ditahan",q:"Benar atau Salah: Menjaga keseimbangan layar yang sehat, dengan aktivitas lain yang juga memuaskan, bisa terasa menyenangkan & memperkaya hidup, bukan hanya berupa 'menahan diri' terus-menerus.",answer:true,explain:"Ketika alternatif non-layar (olahraga, hobi, waktu bersama) benar-benar dinikmati, keseimbangan terasa sebagai kelimpahan, bukan pengorbanan.",hint:"Bisa terasa menyenangkan & memperkaya, atau hanya menahan diri terus?"},
{n:86,type:"mcq",micro:"Skenario: menyeimbangkan tugas kelompok daring & waktu pribadi",q:"Tugas kelompok butuh koordinasi lewat chat yang cukup intens beberapa hari. Cara menjaga keseimbangan tetap terjaga:",options:["Biarkan chat kelompok mengambil semua waktu luang termasuk waktu tidur, sebab tugas kelompok jauh lebih penting daripada istirahat atau kegiatan lainnya","Tetap sisihkan waktu istirahat & aktivitas lain di luar jam koordinasi yang disepakati kelompok, jangan biarkan chat kelompok mengambil semua waktu luang","Abaikan chat kelompok dan jangan membalas apa-apa, supaya waktu istirahatmu aman tanpa mempertimbangkan kerja sama"],answer:1,explain:"Tanggung jawab kelompok penting, tapi tetap bisa dijadwalkan dengan wajar tanpa mengorbankan seluruh waktu istirahat pribadi.",hint:"Sisihkan waktu istirahat + tetap koordinasi wajar, atau siap 24 jam / abaikan kelompok?"},
{n:87,type:"mcq",micro:"Skenario: menemani adik yang terlalu lama di layar",q:"Kamu melihat adikmu sudah lama sekali di depan tablet & sulit diajak berhenti. Cara membantu tanpa konflik besar:",options:["Rebut tablet dari tangannya dan marahi dia di depan keluarga, supaya dia kapok","Biarkan dia terus memakai tablet sampai bosan sendiri, karena tidak perlu ada yang mengajaknya berhenti atau menawarkan kegiatan lain yang menarik","Ajak melakukan aktivitas menarik lain bersama (bukan hanya menyuruh berhenti), sehingga ada pengganti yang menarik, bukan sekadar larangan"],answer:2,explain:"Menawarkan alternatif yang menarik lebih efektif & lebih hangat daripada sekadar melarang atau merebut paksa.",hint:"Ajak aktivitas lain sebagai pengganti, atau merebut paksa / biarkan saja?"},
{n:88,type:"mcq",micro:"Skenario: godaan saat seharusnya tidur",q:"Sudah larut malam & kamu tahu seharusnya tidur, tapi masih ingin 'satu video lagi'. Cara mengatasi momen ini:",options:["Ingat rencana yang sudah dibuat & niat awal (tidur cukup penting untuk besok), lalu benar-benar berhenti meski video berikutnya terlihat menarik","Tonton satu video lagi, lalu satu lagi, karena besok masih bisa tidur siang untuk membayar kurang tidur","Matikan HP dengan marah dan salahkan aplikasinya, lalu berbaring sambil tetap memikirkan video itu sampai pagi tanpa bisa tidur nyenyak"],answer:0,explain:"'Satu video lagi' adalah jebakan klasik desain yang membuat waktu terus molor. Mengingat rencana & komitmen awal membantu benar-benar berhenti.",hint:"Ingat rencana & berhenti, atau lanjutkan 'sekali lagi' / biarkan sampai mengantuk sendiri?"},
{n:89,type:"mcq",micro:"Skenario: menyeimbangkan minat digital yang positif",q:"Kamu sangat menikmati membuat konten kreatif (edit video, menggambar digital) & menghabiskan banyak waktu untuk itu. Cara menilai apakah ini tetap sehat:",options:["Anggap waktu layar yang lama buruk dan wajib dikurangi drastis, tanpa melihat apakah tidur, sekolah, dan hubunganmu baik-baik saja","Periksa apakah tidur, sekolah, & hubunganmu tetap terjaga baik; kalau ya, ini bisa jadi hobi yang sehat meski memakan banyak waktu layar","Teruskan saja tanpa memeriksa, bahkan jika tidur, sekolah, dan hubunganmu mulai terganggu, karena itu hobi yang kamu cintai"],answer:1,explain:"Yang menentukan sehat/tidak bukan semata jumlah waktu, tapi dampaknya pada keseluruhan hidup (tidur, sekolah, hubungan).",hint:"Periksa dampak keseluruhan, atau otomatis tidak sehat / otomatis sehat tanpa periksa?"},
{n:90,type:"order",micro:"Proyek: eksperimen keseimbangan seminggu",q:"Urutkan langkah menjalankan eksperimen keseimbangan layar selama seminggu.",items:["Catat pola waktu layar saat ini sebagai titik awal (baseline)","Pilih 1-2 perubahan kecil untuk dicoba (zona bebas layar, kurangi notifikasi, dll)","Jalankan perubahan itu konsisten selama seminggu, catat perasaan & tantangannya","Bandingkan dengan titik awal & putuskan apakah akan melanjutkan, menyesuaikan, atau mencoba hal lain"],answer:[0,1,2,3],explain:"Catat titik awal → pilih perubahan kecil → jalankan & catat → bandingkan & putuskan. Titik awal penting agar bisa melihat perubahan nyata, bukan sekadar perasaan.",hint:"Mencatat titik awal dilakukan sebelum atau sesudah memilih perubahan yang akan dicoba?"},
{n:91,type:"mcq",micro:"Skenario: tekanan sosial untuk selalu online",q:"Teman-teman mengharapkan kamu selalu cepat membalas chat kapan pun, membuatmu merasa harus terus memeriksa HP. Cara menyeimbangkan:",options:["Membalas seketika setiap saat, termasuk saat belajar dan tidur, supaya teman tetap menyukaimu","Matikan HP berhari-hari tanpa memberi tahu orang lain, sehingga teman bingung dan khawatir, karena itu cara tercepat mengakhiri tuntutan mereka","Komunikasikan dengan baik bahwa kamu tidak selalu bisa membalas instan, & itu wajar; teman yang baik akan mengerti"],answer:2,explain:"Menetapkan & mengomunikasikan batas yang wajar adalah bagian sehat dari hubungan, bukan sikap tidak peduli.",hint:"Komunikasikan batas wajar, atau selalu siap instan / putus semua pertemanan?"},
{n:92,type:"tf",micro:"Keseimbangan adalah perjalanan, bukan tujuan akhir",q:"Benar atau Salah: Menjaga keseimbangan layar lebih tepat dipandang sebagai proses yang terus disesuaikan seiring hidup berubah, bukan target yang sekali dicapai lalu selesai selamanya.",answer:true,explain:"Kebutuhan & godaan berubah seiring waktu (usia, teknologi baru, situasi hidup). Keseimbangan perlu terus disesuaikan, bukan dicapai sekali untuk selamanya.",hint:"Proses berkelanjutan yang disesuaikan, atau target sekali capai selesai?"},
{n:93,type:"mcq",micro:"Skenario: menilai konten sebelum menghabiskan waktu",q:"Sebelum menonton serial baru yang katanya 'bisa habis dalam semalam', cara menyikapi dengan bijak:",options:["Rencanakan dulu berapa episode/waktu yang wajar untuk sekali duduk, & tetap patuhi rencana meski ceritanya sangat menarik","Tonton terus sampai habis dalam semalam tanpa rencana, karena kalau berhenti di tengah cerita kamu penasaran, lebih baik sekalian selesai","Larang diri menonton serial seterusnya, termasuk saat liburan, karena semua serial membuat ketagihan"],answer:0,explain:"Merencanakan batas SEBELUM mulai lebih efektif daripada mencoba menahan diri di tengah momen paling menegangkan cerita.",hint:"Rencanakan batas dulu & patuhi, atau tonton tanpa rencana / hindari total?"},
{n:94,type:"mcq",micro:"Skenario: menyeimbangkan waktu belajar & main setelah pulang sekolah",q:"Sepulang sekolah, kamu ingin langsung main game tapi juga ada tugas yang harus dikerjakan. Cara yang membantu keseimbangan jangka panjang:",options:["Main game sepuasnya dulu sampai larut malam, baru kerjakan tugas terburu-buru, sebab bermain lebih dulu membuat pikiran lebih segar","Buat kesepakatan dengan diri sendiri: kerjakan tugas dulu (atau sebagian), baru nikmati waktu bermain dengan tenang tanpa rasa bersalah","Abaikan keinginan bermain dan hukum dirimu setiap kali tergoda, sebab hanya dengan menyiksa diri kamu bisa disiplin"],answer:1,explain:"Menyelesaikan kewajiban dulu membuat waktu bermain terasa lebih tenang & tidak dibayangi rasa bersalah atau kekhawatiran soal tugas.",hint:"Tugas dulu baru main tenang, atau main dulu berharap sempat / tak pernah main?"},
{n:95,type:"tf",micro:"Kesadaran mengalahkan aturan kaku",q:"Benar atau Salah: Memahami PRINSIP di balik keseimbangan layar (kenapa tidur, gerak, & hubungan penting) lebih membantu jangka panjang dibanding hanya mematuhi aturan kaku tanpa memahami alasannya.",answer:true,explain:"Pemahaman membuat kita bisa menyesuaikan diri di situasi baru; aturan kaku tanpa pemahaman mudah dilanggar begitu situasinya sedikit berbeda.",hint:"Pemahaman prinsip lebih membantu, atau aturan kaku tanpa pemahaman cukup?"},
{n:96,type:"mcq",micro:"Skenario: menjadi teladan digital yang seimbang",q:"Adik/sepupu yang lebih muda mengamati kebiasaan layarmu. Cara menjadi teladan yang baik:",options:["Menasihati mereka panjang lebar tentang bahayanya layar, sambil tetap memakai layar tanpa batas sendiri, karena kata-kata lebih berpengaruh daripada perbuatan nyata","Menyembunyikan kebiasaan layarmu dari mereka hanya saat kamu ketahuan, lalu bersikap berbeda di belakang, karena yang penting hanya terlihat baik di depan mereka","Praktikkan sendiri kebiasaan seimbang yang kamu yakini (bukan hanya menasihati), karena tindakan nyata lebih berpengaruh dari kata-kata"],answer:2,explain:"Anak-anak & remaja belajar lebih banyak dari yang mereka lihat dilakukan daripada dari nasihat verbal semata.",hint:"Praktikkan sendiri sebagai teladan, atau menasihati tanpa mempraktikkan / anggap tak berpengaruh?"},
{n:97,type:"mcq",micro:"Menilai pemahaman diri",q:"Tanda kamu sudah cukup memahami keseimbangan layar & kesehatan digital:",options:["Kamu sadar pola pemakaianmu, bisa membuat pilihan sengaja (bukan otomatis), & tahu kapan perlu menyesuaikan atau minta bantuan","Kamu hafal angka batas waktu layar yang disarankan tetapi tak memperhatikan pola pemakaianmu sendiri dan tetap memakai layar otomatis","Kamu menjauhi layar dan perangkat digital seterusnya karena takut kecanduan, bahkan untuk belajar dan berkomunikasi"],answer:0,explain:"Pemahaman sejati terlihat dari kesadaran & pilihan nyata, bukan sekadar hafalan fakta atau penghindaran ekstrem.",hint:"Sadar & bisa memilih sengaja, atau hafal fakta tanpa berubah / hindari total?"},
{n:98,type:"mcq",micro:"Keseimbangan layar & kualitas hidup",q:"Seseorang dengan keseimbangan layar yang sehat cenderung memiliki...",options:["Lebih sedikit energi, tidur berantakan, dan hubungan makin renggang, tetapi merasa terhibur oleh layar sepanjang hari","Lebih banyak energi, tidur lebih baik, hubungan yang lebih kaya, & tetap bisa menikmati manfaat teknologi","Hidup tanpa teknologi karena menolak perangkat digital, sehingga tidak mendapat manfaat belajar, komunikasi, maupun hiburan"],answer:1,explain:"Keseimbangan yang sehat mendukung berbagai aspek kesejahteraan sambil tetap membuka akses pada manfaat dunia digital.",hint:"Lebih banyak energi & hubungan kaya, atau membosankan / tak ada beda?"},
{n:99,type:"mcq",micro:"Inti keterampilan",q:"Inti dari 'keseimbangan layar & kesehatan digital':",options:["Pakai layar sebanyak yang kamu mau setiap hari tanpa perlu memahami cara aplikasi dirancang atau memeriksa kebiasaan, dan biarkan semuanya berjalan otomatis seperti biasa","Hindari layar dan teknologi seumur hidup, jangan belajar tentang cara aplikasi bekerja, dan anggap semua orang yang memakainya bermasalah","Sadari pola pemakaianmu, pahami cara aplikasi dirancang menarik perhatian, buat pilihan sengaja (bukan otomatis), & jaga hal penting lain (tidur, gerak, hubungan) tetap terjaga"],answer:2,explain:"Sadar + paham desain + pilih sengaja + jaga prioritas lain. Ini prinsip yang membuat teknologi jadi alat yang melayani hidup kita, bukan sebaliknya.",hint:"Sadar + pilih sengaja + jaga prioritas, atau hindari total / pakai sebanyak mungkin?"},
{n:100,type:"open",micro:"Kapstone: rencana kesehatan digital pribadi",q:"Tulis 'rencana kesehatan digital' pribadimu untuk dipegang seterusnya. Sertakan: (a) 3-5 prinsip yang akan kamu pegang, (b) untuk tiap prinsip, satu kebiasaan konkret, (c) satu 'zona/waktu bebas layar' tetap dalam hidupmu, (d) bagaimana kamu akan mengenali tanda bahwa keseimbanganmu mulai bergeser & butuh penyesuaian, (e) bagaimana kamu akan meninjau & memperbarui rencana ini seiring waktu.",explain:"Jawaban baik: 3-5 prinsip yang mencakup kesadaran, tidur, aktivitas fisik & hubungan, pemilihan konten sengaja, & menikmati tanpa rasa bersalah berlebihan, masing-masing dengan kebiasaan konkret yang benar-benar bisa dilakukan; zona bebas layar yang spesifik & tetap; tanda pergeseran yang konkret & bisa dikenali (bukan generik); & rencana peninjauan berkala yang benar-benar terjadwal (bukan 'akan sering mengecek').",hint:"Bagian (d) & (e) yang paling sering lemah, buat tanda pergeseran & jadwal peninjauan benar-benar spesifik & bisa diperiksa, bukan niat umum.",sample:"(a) & (b) Prinsip & kebiasaan: (1) 'Aku sadar untuk apa aku membuka sebuah aplikasi', kebiasaan, bertanya sebentar pada diri sendiri sebelum membuka aplikasi hiburan, 'aku buka ini untuk apa & berapa lama?'. (2) 'Tidurku tidak dikorbankan untuk layar', kebiasaan, berhenti memakai HP 30-45 menit sebelum jam tidur & mengisi dayanya di ruang lain. (3) 'Aku menjaga waktu untuk bergerak & bertemu orang langsung', kebiasaan, minimal 30 menit aktivitas fisik & satu momen tanpa layar bersama keluarga/teman setiap hari. (4) 'Aku memilih konten dengan sengaja, bukan mengikuti arus rekomendasi terus-menerus', kebiasaan, sesekali mencari sesuatu secara spesifik untuk ditonton/dibaca, bukan hanya scroll rekomendasi tanpa henti. (5) 'Aku menikmati hiburan digital tanpa rasa bersalah selama tanggung jawabku terpenuhi', kebiasaan, menyelesaikan tugas/kewajiban dulu sebelum menikmati waktu layar untuk hiburan dengan tenang. (c) Zona/waktu bebas layar tetap: saat makan bersama keluarga & 30-45 menit sebelum tidur setiap malam. (d) Mengenali tanda pergeseran: aku akan waspada bila mulai sering merasa 'kok udah sejam' tanpa sadar, bila tidurku mulai berantakan lagi, bila aku merasa gelisah/marah berlebihan saat tidak bisa memakai HP, atau bila aku mulai lebih memilih layar daripada bertemu teman/keluarga yang sebelumnya kunikmati; kalau tanda-tanda ini muncul & aku sudah coba perbaiki sendiri tapi tetap sulit, aku akan bicara dengan orang tuaku. (e) Meninjau rencana: aku akan meluangkan waktu sebentar setiap awal bulan untuk mengecek data waktu layar di HP-ku, membandingkan dengan bulan sebelumnya, & bertanya jujur pada diriku apakah prinsip-prinsip ini masih kupraktikkan atau mulai terlupakan, lalu menyesuaikan rencana bila situasi hidupku berubah (mis. masa ujian, liburan panjang)."},
];
